// Command orb-scheduler-core serves the HTTP API described in README.md.
package main

import (
	"log"
	"os"

	"github.com/Bob-xisuke/orb-scheduler-core/internal/api"
	"github.com/Bob-xisuke/orb-scheduler-core/internal/store"
)

func main() {
	address := os.Getenv("ADDR")
	if address == "" {
		address = "127.0.0.1:8080"
	}
	databasePath := os.Getenv("DB_PATH")
	if databasePath == "" {
		databasePath = "orb-scheduler-core.db"
	}

	st, err := store.Open(databasePath)
	if err != nil {
		log.Fatalf("open store: %v", err)
	}
	defer st.Close()

	if err := api.NewRouter(st).Run(address); err != nil {
		log.Fatalf("serve: %v", err)
	}
}

package api

import (
	"net/http"

	"github.com/gin-gonic/gin"

	"github.com/Bob-xisuke/orb-scheduler-core/internal/service"
	"github.com/Bob-xisuke/orb-scheduler-core/internal/store"
)

// NewRouter wires the public HTTP surface: health and the placements API. Every
// entry keeps the error shape described in README.md.
func NewRouter(st *store.Store) *gin.Engine {
	gin.SetMode(gin.ReleaseMode)
	router := gin.New()
	router.Use(gin.Recovery())

	router.GET("/healthz", func(c *gin.Context) {
		if err := st.Ping(); err != nil {
			c.JSON(http.StatusServiceUnavailable, gin.H{"error": gin.H{"code": "storage_unavailable", "message": "database is not available"}})
			return
		}
		c.JSON(http.StatusOK, gin.H{"status": "ok", "database": "ok"})
	})

	h := &placementHandler{svc: service.New(st)}
	router.POST("/v1/placements", h.createPlacement)
	router.GET("/v1/placements", h.listPlacements)

	router.NoRoute(func(c *gin.Context) {
		c.JSON(http.StatusNotFound, gin.H{"error": gin.H{"code": "route_not_found", "message": "no route matches this path"}})
	})
	return router
}

package store

import "github.com/Bob-xisuke/orb-scheduler-core/internal/model"

// Compatibility re-exports. The record model, the defaulting and
// content-equality rules, and the storage-contract vocabulary live in
// internal/model so that parsing, scheduling and idempotency judgment — and
// in-memory storage doubles — never depend on this package's SQLite driver.
// Existing callers that refer to these names through package store keep
// working unchanged: the aliases are the very same types and functions.

type (
	// Placement is one stored scheduling decision; see model.Placement.
	Placement = model.Placement
	// Node is one candidate node offered by a placement request.
	Node = model.Node
	// Resources is a workload request or a node capacity.
	Resources = model.Resources
	// ListFilter narrows List; empty fields are ignored. Node never matches
	// a rejected record.
	ListFilter = model.ListFilter
)

// ErrNotFound is returned by Get when no placement matches the identity.
var ErrNotFound = model.ErrNotFound

// NormalizeInput fills the documented omitted-field defaults in place; see
// model.NormalizeInput, the single definition shared by every entry point.
var NormalizeInput = model.NormalizeInput

// SameInput reports whether the request halves of two placements are equal
// under the documented comparison; see model.SameInput.
var SameInput = model.SameInput

// Package service implements placement acceptance: the trial scheduling
// decision together with idempotent, conflict-aware registration. Accept is
// the single business entry point for a parsed placement request; it has no
// dependency on the HTTP transport.
package service

import (
	"context"
	"errors"
	"fmt"

	"github.com/Bob-xisuke/orb-scheduler-core/internal/model"
)

// Scheduling outcomes recorded on every placement.
const (
	StatusPlaced   = "placed"
	StatusRejected = "rejected"
	ReasonNoNode   = "no_eligible_node"
)

// Outcome classifies what Accept did with a submission.
type Outcome int

const (
	// Created means the (namespace, name) identity was registered for the
	// first time by this call.
	Created Outcome = iota
	// Identical means the identity already existed with the same request
	// content; the returned record is the original one.
	Identical
	// Conflict means the identity already existed with different content;
	// the returned record is the untouched original.
	Conflict
)

// ErrStorageUnavailable is the sentinel wrapped for every persistence failure.
var ErrStorageUnavailable = errors.New("storage unavailable")

// Service holds the collaborators needed to accept placements.
type Service struct {
	st Store
}

// New builds the acceptance service over a Store. Production callers pass the
// SQLite-backed *store.Store; tests may pass any implementation of the
// contract without changing Accept or Query behavior.
func New(st Store) *Service {
	return &Service{st: st}
}

// Accept runs the trial placement and registers its result under the
// (namespace, name) identity. The first valid submission for an identity is
// stored and reported as Created; a later submission carrying the same request
// content is reported as Identical with the original record; one carrying
// different content is reported as Conflict and never changes the stored
// record. Scheduling results alone do not count as equal content. Input
// validation is expected to have happened before this call.
func (s *Service) Accept(ctx context.Context, p *model.Placement) (*model.Placement, Outcome, error) {
	// Fill omitted-field defaults through the single shared definition so
	// the trial, the stored record and the content comparison all see the
	// same input. The candidate array's order is left untouched.
	model.NormalizeInput(p)
	p.Status, p.Node, p.Reason = schedule(p)

	stored, created, err := s.st.Submit(ctx, p)
	if err != nil {
		return nil, Created, storageError(err)
	}
	if created {
		return stored, Created, nil
	}

	same, err := model.SameInput(p, stored)
	if err != nil {
		return nil, Created, storageError(err)
	}
	if !same {
		return stored, Conflict, nil
	}
	return stored, Identical, nil
}

func storageError(err error) error {
	return fmt.Errorf("accept placement: %w: %w", ErrStorageUnavailable, err)
}

package api

import (
	"errors"
	"io"
	"net/http"
	"net/url"

	"github.com/gin-gonic/gin"

	"github.com/Bob-xisuke/orb-scheduler-core/internal/placement"
	"github.com/Bob-xisuke/orb-scheduler-core/internal/service"
)

// Error codes published by the placements API.
const (
	codeInvalidInput = "InvalidPlacementInputError"
	codeNotFound     = "PlacementNotFoundError"
	codeConflict     = "PlacementConflictError"
	codeStorageDown  = "storage_unavailable"
)

type placementHandler struct {
	svc *service.Service
}

func writeAPIError(c *gin.Context, status int, code, message string) {
	c.AbortWithStatusJSON(status, gin.H{"error": gin.H{"code": code, "message": message}})
}

// createPlacement handles POST /v1/placements. The transport layer only
// parses and validates the request and maps the business acceptance outcome
// to its HTTP status; scheduling and idempotency/conflict decisions belong to
// service.Accept. The strict parsing rules live in package placement and are
// shared with direct, non-HTTP callers.
func (h *placementHandler) createPlacement(c *gin.Context) {
	body, err := io.ReadAll(c.Request.Body)
	if err != nil {
		writeAPIError(c, http.StatusBadRequest, codeInvalidInput, "invalid placement input")
		return
	}
	p, err := placement.ParsePlacementInput(body)
	if err != nil {
		writeAPIError(c, http.StatusBadRequest, codeInvalidInput, "invalid placement input")
		return
	}

	stored, outcome, err := h.svc.Accept(c.Request.Context(), p)
	if err != nil {
		writeAPIError(c, http.StatusServiceUnavailable, codeStorageDown, "database is not available")
		return
	}
	switch outcome {
	case service.Created:
		c.JSON(http.StatusCreated, stored)
	case service.Identical:
		c.JSON(http.StatusOK, stored)
	case service.Conflict:
		writeAPIError(c, http.StatusConflict, codeConflict,
			"a placement with this namespace and name already exists with different content")
	}
}

// listPlacements handles GET /v1/placements, both the single-record form
// (namespace+name) and the filtered-list form. The transport layer only
// decodes the raw query string and maps the business result to its HTTP
// status; all parameter rules and filtering belong to service.Query.
func (h *placementHandler) listPlacements(c *gin.Context) {
	values, err := url.ParseQuery(c.Request.URL.RawQuery)
	if err != nil {
		writeAPIError(c, http.StatusBadRequest, codeInvalidInput, "invalid placement query")
		return
	}

	result, err := h.svc.Query(c.Request.Context(), values)
	if errors.Is(err, service.ErrInvalidPlacementQuery) {
		writeAPIError(c, http.StatusBadRequest, codeInvalidInput, "invalid placement query")
		return
	}
	if errors.Is(err, service.ErrPlacementNotFound) {
		writeAPIError(c, http.StatusNotFound, codeNotFound, "placement not found")
		return
	}
	if err != nil {
		writeAPIError(c, http.StatusServiceUnavailable, codeStorageDown, "database is not available")
		return
	}
	if result.Record != nil {
		c.JSON(http.StatusOK, result.Record)
		return
	}
	c.JSON(http.StatusOK, gin.H{"items": result.Items})
}

