1	// Package fakestore provides an in-memory implementation of the storage
2	// contract defined by package service. It lets business-logic tests run the
3	// real accept and query flows without creating a SQLite file: stored records
4	// are controlled by the test, every call is recorded, and each method can be
5	// switched to fail with a chosen error. It carries no scheduling, defaulting
6	// or comparison rules of its own — those stay in package service.
7	package fakestore
8	
9	import (
10		"context"
11		"encoding/json"
12		"fmt"
13		"sort"
14		"sync"
15	
16		"github.com/Bob-xisuke/orb-scheduler-core/internal/model"
17	)
18	
19	// SubmitCall records one Submit invocation.
20	type SubmitCall struct {
21		// Record is a deep copy of the placement as the service submitted it,
22		// after its own normalization and trial scheduling.
23		Record *model.Placement
24	}
25	
26	// GetCall records one Get invocation.
27	type GetCall struct {
28		Namespace string
29		Name      string
30	}
