2	
3	import (
4		"context"
5		"errors"
6		"net/url"
7		"testing"
8	
9		"github.com/Bob-xisuke/orb-scheduler-core/internal/model"
10		"github.com/Bob-xisuke/orb-scheduler-core/internal/service/fakestore"
11	)
12	
13	// This suite runs the Query business flow against the in-memory fakestore
14	// double: no SQLite file is created, the records and errors storage returns
15	// are controlled directly, and call recording proves which queries never
16	// reach storage. The SQLite-backed tests in query_test.go remain the
17	// regression for the real storage path.
18	
19	func mustValues(t *testing.T, raw string) url.Values {
20		t.Helper()
21		values, err := url.ParseQuery(raw)
22		if err != nil {
23			t.Fatalf("parse %q: %v", raw, err)
24		}
25		return values
26	}
27	
28	// placedRecord builds a stored-looking record without running Accept, so
29	// tests control exactly what the storage layer holds.
30	func placedRecord(namespace, name, queue, node string) *model.Placement {
31		return &model.Placement{
32			Namespace: namespace,
33			Name:      name,
34			Queue:     queue,
35			Priority:  1,
36			Resources: model.Resources{CPU: 100, Memory: 64},
37			Selector:  map[string]string{},
38			Nodes:     []model.Node{{Name: node, CPU: 1000, Memory: 512, Labels: map[string]string{}}},
39			Status:    StatusPlaced,
40			Node:      &node,
41		}
42	}
43	
44	func rejectedRecord(namespace, name, queue string) *model.Placement {
45		reason := ReasonNoNode
46		return &model.Placement{
47			Namespace: namespace,
48			Name:      name,
49			Queue:     queue,
50			Priority:  1,
51			Resources: model.Resources{CPU: 100, Memory: 64},
52			Selector:  map[string]string{},
53			Nodes:     []model.Node{},
54			Status:    StatusRejected,
55			Reason:    &reason,
56		}
57	}
58	
59	func TestQueryWithFakeInvalidParameterSetsNeverReachStorage(t *testing.T) {
60		fake, svc := newFakeService()
61		fake.Seed(placedRecord("team-a", "job-1", "default", "node-a"))
62	
63		cases := map[string]url.Values{
64			"unknown key":        {"bogus": {"x"}},
65			"known plus unknown": {"namespace": {"a"}, "bogus": {"x"}},
66			"repeated value":     {"namespace": {"a", "b"}},
67			"empty value":        {"namespace": {""}},
68			"name without ns":    {"name": {"job"}},
69			"name with queue":    {"namespace": {"a"}, "name": {"job"}, "queue": {"q"}},
70			"name with node":     {"namespace": {"a"}, "name": {"job"}, "node": {"n"}},
71		}
72		for label, values := range cases {
73			result, err := svc.Query(context.Background(), values)
74			if !errors.Is(err, ErrInvalidPlacementQuery) {
75				t.Errorf("%s: err = %v, want ErrInvalidPlacementQuery", label, err)
76			}
